using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class SaveAfterSecondsWrapup {public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop play mode before final save");if(UnityEngine.Object.FindObjectsByType<Camera>().Any(c=>c.name=="TemporaryWallReviewCamera"))throw new Exception("Review camera remains");AssetDatabase.SaveAssets();if(!EditorSceneManager.SaveOpenScenes())throw new Exception("Scene save failed");var s=SceneManager.GetActiveScene();var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();int miss=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));if(miss!=0)throw new Exception("Missing script");string r=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/B5_Clinical_Tone_20261103"));File.WriteAllText(r+"/wrapup_save.json",JsonConvert.SerializeObject(new{scene=s.path,saved=true,dirty=s.isDirty,missingScripts=miss,ceilingTransforms=ts.Where(t=>t.name.Contains("Ceiling")).Select(t=>new{path=t.name,rotation=new[]{t.localEulerAngles.x,t.localEulerAngles.y,t.localEulerAngles.z}})},Formatting.Indented));return "Assets and open scenes saved; no missing scripts";}}
